create temp table wh_delta_members on commit drop as
select
    item ->> 'canonicalKey' as canonical_key,
    (item ->> 'memberId')::uuid as member_id,
    item ->> 'paxName' as pax_name,
    nullif(item ->> 'homeAo', '') as home_ao,
    (item ->> 'firstPostDate')::date as first_post_date
from wh_delta_payload payload
cross join lateral jsonb_array_elements(payload.document -> 'members') member(item);
alter table wh_delta_members add primary key (canonical_key);
create unique index wh_delta_members_member_id_unique on wh_delta_members(member_id);

create temp table wh_delta_sessions on commit drop as
select
    item ->> 'sessionKey' as session_key,
    (item ->> 'sessionId')::uuid as session_id,
    (item ->> 'date')::date as session_date,
    item ->> 'aoName' as ao_name,
    (item ->> 'aoId')::uuid as ao_id,
    (item ->> 'siteId')::uuid as site_id,
    nullif(item ->> 'eventName', '') as event_name,
    item ->> 'workoutType' as workout_type,
    item -> 'attendeeIds' as attendee_ids,
    item -> 'qAssignments' as q_assignments,
    item -> 'fngs' as fngs
from wh_delta_payload payload
cross join lateral jsonb_array_elements(payload.document -> 'sessions') session(item);
alter table wh_delta_sessions add primary key (session_key);
create unique index wh_delta_sessions_session_id_unique on wh_delta_sessions(session_id);

create temp table wh_delta_expected_sessions on commit drop as
select
    source.*,
    coalesce((select array_agg((assignment.value ->> 'memberId')::uuid order by (assignment.value ->> 'memberId')::uuid)
              from jsonb_array_elements(source.q_assignments) assignment(value)), '{}'::uuid[]) as q_ids,
    (select (assignment.value ->> 'memberId')::uuid
     from jsonb_array_elements(source.q_assignments) assignment(value)
     order by case when assignment.value ->> 'role' = 'q' then 0 else 1 end,
              (assignment.value ->> 'memberId')::uuid limit 1) as q_id
from wh_delta_sessions source;

create temp table wh_delta_expected_aos on commit drop as
select (item ->> 'id')::uuid as id, item ->> 'name' as name
from wh_delta_payload payload
cross join lateral jsonb_array_elements(payload.document #> '{configuration,aos}') ao(item);
create temp table wh_delta_expected_sites on commit drop as
select (item ->> 'id')::uuid as id, item ->> 'name' as name
from wh_delta_payload payload
cross join lateral jsonb_array_elements(payload.document #> '{configuration,sites}') site(item);

create temp table wh_delta_context (apply_mode text not null, doge_profile_id uuid not null) on commit drop;
create temp table wh_delta_inserted_members (id uuid primary key) on commit drop;
create temp table wh_delta_inserted_sessions (id uuid primary key) on commit drop;

-- Snapshot every pre-existing West Houston member/session. Postflight proves this migration changed none of them.
create temp table wh_delta_preserved_members on commit drop as
select member.id, to_jsonb(member) as snapshot
from public.members member
where member.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid;
alter table wh_delta_preserved_members add primary key (id);
create temp table wh_delta_preserved_sessions on commit drop as
select session.id, to_jsonb(session) as snapshot
from public.sessions session
where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid;
alter table wh_delta_preserved_sessions add primary key (id);

select region.id from public.regions region
where region.id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid for update;

do $wh_delta_preflight$
declare
    contract jsonb;
    target_members integer;
    target_sessions integer;
    actual_sessions bigint;
    actual_attendance bigint;
    actual_qs bigint;
    actual_fngs bigint;
    doge_profile uuid;
begin
    select document -> 'contract' into contract from wh_delta_payload;
    if contract ->> 'schemaVersion' <> 'west-houston-append-only-delta-v1'
       or contract ->> 'regionId' <> '7298b632-4d9a-542f-b65d-d416e5c1e631'
       or contract ->> 'v1CanonicalSha256' <> 'f1c677cf99e8aa9e15595d4ed3fb796f2d624d741868395786b097108114c16a'
       or contract ->> 'v2CanonicalSha256' <> '38f66ec805d54576c7c017c9bf9e16b45016cef4351842753bab712105cee2fd'
       or contract ->> 'humanManifestSha256' <> '8e1c752188b95ed3e04100e481a75bcac5a2294a11693604391e956ee6705c75' then
        raise exception 'West Houston delta embedded contract mismatch';
    end if;
    if (select count(*) from wh_delta_members) <> 4
       or (select count(*) from wh_delta_sessions) <> 36
       or (select coalesce(sum(jsonb_array_length(attendee_ids)), 0) from wh_delta_sessions) <> 393
       or (select coalesce(sum(jsonb_array_length(q_assignments)), 0) from wh_delta_sessions) <> 35
       or (select coalesce(sum(jsonb_array_length(fngs)), 0) from wh_delta_sessions) <> 3 then
        raise exception 'West Houston delta embedded payload counts are invalid';
    end if;
    if not exists (select 1 from public.regions where id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
                   and name = 'F3 West Houston' and environment = 'production') then
        raise exception 'West Houston production region contract mismatch';
    end if;
    if exists ((select ao.id, ao.name from public.aos ao where ao.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
                except select id, name from wh_delta_expected_aos)
               union all
               (select id, name from wh_delta_expected_aos except
                select ao.id, ao.name from public.aos ao where ao.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)) then
        raise exception 'West Houston AO configuration differs from the approved configuration';
    end if;
    if exists ((select site.id, site.name from public.sites site where site.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
                except select id, name from wh_delta_expected_sites)
               union all
               (select id, name from wh_delta_expected_sites except
                select site.id, site.name from public.sites site where site.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)) then
        raise exception 'West Houston site configuration differs from the approved configuration';
    end if;
    select profile.id into doge_profile from public.profiles profile
    where profile.member_id = '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid;
    if doge_profile is null or (select count(*) from public.profiles where member_id = '0ec36c8a-3354-5b95-9b94-27013a04c3e6'::uuid) <> 1 then
        raise exception 'DOGE profile contract mismatch';
    end if;
    if not exists (select 1 from public.members where id = '70fa4a9a-b521-57d0-8fe5-07951f566a6f'::uuid
        and region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid and pax_name = 'Zillow' and home_ao = 'The Branch'
        and first_post_date = '2022-10-28' and status = 'active') then
        raise exception 'Historical Zillow production precondition mismatch';
    end if;
    if not exists (select 1 from public.sessions where id = '3847bd2c-3bb7-54f4-adfb-a7069cd51f00'::uuid
        and region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid and date = '2026-09-24' and ao_name = 'The Iron Gate'
        and jsonb_array_length(coalesce(attendee_ids, '[]'::jsonb)) = 9
        and cardinality(coalesce(q_ids, '{}'::uuid[])) = 0 and jsonb_array_length(coalesce(fngs, '[]'::jsonb)) = 0)
       or not exists (select 1 from public.sessions where id = 'df0fc2bc-8ba8-57f8-8d29-9900939d2889'::uuid
        and region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid and date = '2026-09-24' and ao_name = 'The Iron Gate'
        and jsonb_array_length(coalesce(attendee_ids, '[]'::jsonb)) = 17
        and cardinality(coalesce(q_ids, '{}'::uuid[])) = 5 and jsonb_array_length(coalesce(fngs, '[]'::jsonb)) = 0) then
        raise exception 'Retained Iron Gate production precondition mismatch';
    end if;
    if exists (select 1 from wh_delta_sessions where session_id in ('3847bd2c-3bb7-54f4-adfb-a7069cd51f00'::uuid, 'df0fc2bc-8ba8-57f8-8d29-9900939d2889'::uuid)) then
        raise exception 'A retained Iron Gate session is a delta target';
    end if;
    if exists (select 1 from wh_delta_expected_sessions source
        cross join lateral jsonb_array_elements_text(source.attendee_ids) attendee(value)
        where attendee.value::uuid = '70fa4a9a-b521-57d0-8fe5-07951f566a6f'::uuid)
       or exists (select 1 from wh_delta_expected_sessions source
        cross join lateral jsonb_array_elements(source.q_assignments) q(value)
        where (q.value ->> 'memberId')::uuid = '70fa4a9a-b521-57d0-8fe5-07951f566a6f'::uuid)
       or exists (select 1 from wh_delta_expected_sessions source
        cross join lateral jsonb_array_elements(source.fngs) fng(value)
        where (fng.value ->> 'memberId')::uuid = '70fa4a9a-b521-57d0-8fe5-07951f566a6f'::uuid) then
        raise exception 'Historical Zillow appears in the delta session payload';
    end if;
    if exists (select 1 from wh_delta_expected_sessions source
        cross join lateral jsonb_array_elements(source.q_assignments) q(value)
        where not (source.attendee_ids ? (q.value ->> 'memberId')))
       or exists (select 1 from wh_delta_expected_sessions source
        cross join lateral jsonb_array_elements(source.fngs) fng(value)
        where not (source.attendee_ids ? (fng.value ->> 'memberId'))
           or (fng.value ->> 'memberId')::uuid = any(source.q_ids)) then
        raise exception 'Delta contains a missing attendee or Q/FNG contradiction';
    end if;
    if exists (select 1 from wh_delta_expected_sessions source
        cross join lateral jsonb_array_elements_text(source.attendee_ids) attendee(value)
        left join public.members actual on actual.id = attendee.value::uuid
        left join wh_delta_members target on target.member_id = attendee.value::uuid
        where target.member_id is null
          and (actual.id is null or actual.region_id <> '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid)) then
        raise exception 'A delta attendance member is absent from the West Houston canonical roster';
    end if;
    if exists (select 1 from public.members actual cross join wh_delta_members expected
        where actual.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid and actual.id <> expected.member_id
          and regexp_replace(lower(coalesce(actual.pax_name, '')), '[^a-z0-9]+', '', 'g') =
              regexp_replace(lower(expected.pax_name), '[^a-z0-9]+', '', 'g')
          and not (expected.member_id = 'e93a4b68-1bc4-5728-89a5-73628205286a'::uuid
                   and actual.id = '70fa4a9a-b521-57d0-8fe5-07951f566a6f'::uuid)) then
        raise exception 'An unexpected existing West Houston member collides with a delta PAX name';
    end if;
    if exists (select 1 from public.sessions actual join wh_delta_expected_sessions expected on expected.session_id = actual.id
        where actual.region_id <> '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid or actual.date <> expected.session_date::text
           or actual.ao_name is distinct from expected.ao_name or actual.ao_id is distinct from expected.ao_id
           or actual.site_id is distinct from expected.site_id or actual.q_id is distinct from expected.q_id
           or coalesce(actual.q_ids, '{}'::uuid[]) is distinct from expected.q_ids
           or coalesce(actual.attendee_ids, '[]'::jsonb) is distinct from expected.attendee_ids
           or coalesce(actual.fngs, '[]'::jsonb) is distinct from expected.fngs
           or actual.notes is distinct from expected.event_name
           or actual.created_at <> floor(extract(epoch from expected.session_date::timestamptz) * 1000)::bigint
           or actual.created_by_user_id is distinct from doge_profile or actual.start_time is not null
           or actual.attendance_review_status <> 'not_required') then
        raise exception 'An existing delta session conflicts with the approved exact row';
    end if;
    if exists (select 1 from public.members actual join wh_delta_members expected on expected.member_id = actual.id
        where actual.region_id <> '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid or actual.pax_name is distinct from expected.pax_name
           or actual.real_name is not null or actual.home_ao is distinct from expected.home_ao
           or actual.first_post_date <> expected.first_post_date::text or actual.status <> 'active') then
        raise exception 'An existing delta member conflicts with the approved exact row';
    end if;
    if exists (select 1 from public.sessions actual join wh_delta_expected_sessions expected
        on actual.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid and actual.date = expected.session_date::text
       and actual.ao_name = expected.ao_name and actual.id <> expected.session_id) then
        raise exception 'A non-target West Houston session already occupies a delta AO/date';
    end if;
    select count(*) into target_members from public.members actual join wh_delta_members target on target.member_id = actual.id;
    select count(*) into target_sessions from public.sessions actual join wh_delta_sessions target on target.session_id = actual.id;
    select count(*), coalesce(sum(jsonb_array_length(coalesce(attendee_ids, '[]'::jsonb))), 0),
           coalesce(sum(cardinality(coalesce(q_ids, '{}'::uuid[]))), 0),
           coalesce(sum(jsonb_array_length(coalesce(fngs, '[]'::jsonb))), 0)
    into actual_sessions, actual_attendance, actual_qs, actual_fngs
    from public.sessions where region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid;
    if target_members = 0 and target_sessions = 0
       and actual_sessions = 3742 and actual_attendance = 43132
       and actual_qs = 3636 and actual_fngs = 494 then
        insert into wh_delta_context values ('apply', doge_profile);
    elsif target_members = 4 and target_sessions = 36
       and actual_sessions = 3778 and actual_attendance = 43525
       and actual_qs = 3671 and actual_fngs = 497 then
        insert into wh_delta_context values ('rerun', doge_profile);
    else
        raise exception 'West Houston delta state is neither exact baseline nor exact applied state (members %, sessions %, totals %/%/%/%)',
            target_members, target_sessions, actual_sessions, actual_attendance, actual_qs, actual_fngs;
    end if;
end;
$wh_delta_preflight$;

with inserted as (
    insert into public.members (id, region_id, pax_name, real_name, home_ao, first_post_date, status)
    select member_id, '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid, pax_name, null, home_ao, first_post_date::text, 'active'
    from wh_delta_members where (select apply_mode from wh_delta_context) = 'apply'
    order by canonical_key returning id
) insert into wh_delta_inserted_members select id from inserted;

with inserted as (
    insert into public.sessions (id, region_id, date, ao_name, q_id, attendee_ids, fngs, notes, created_at, q_ids,
                                 created_by_user_id, start_time, attendance_review_status, ao_id, site_id)
    select expected.session_id, '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid, expected.session_date::text, expected.ao_name, expected.q_id,
           expected.attendee_ids, expected.fngs, expected.event_name,
           floor(extract(epoch from expected.session_date::timestamptz) * 1000)::bigint, expected.q_ids,
           context.doge_profile_id, null, 'not_required', expected.ao_id, expected.site_id
    from wh_delta_expected_sessions expected cross join wh_delta_context context
    where context.apply_mode = 'apply' order by expected.session_date, expected.session_id returning id
) insert into wh_delta_inserted_sessions select id from inserted;

do $wh_delta_derived_data$
declare target record; context record;
begin
    select * into context from wh_delta_context;
    if context.apply_mode = 'apply' then
        if (select count(*) from wh_delta_inserted_members) <> 4
           or (select count(*) from wh_delta_inserted_sessions) <> 36 then
            raise exception 'West Houston delta inserted-row count mismatch';
        end if;
        for target in select member_id from wh_delta_members order by canonical_key loop
            perform public.upsert_region_participant('7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid, target.member_id, null, 'historic_import', context.doge_profile_id);
        end loop;
        for target in select session_id from wh_delta_sessions order by session_date, session_id loop
            perform public.sync_region_participants_for_session(target.session_id);
        end loop;
        perform public.rebuild_member_stats_for_region('7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid);
    elsif (select count(*) from wh_delta_inserted_members) <> 0 or (select count(*) from wh_delta_inserted_sessions) <> 0 then
        raise exception 'West Houston rerun unexpectedly inserted rows';
    end if;
end;
$wh_delta_derived_data$;

do $wh_delta_postflight$
declare
    actual_sessions bigint; actual_attendance bigint; actual_qs bigint; actual_fngs bigint;
begin
    if (select count(*) from public.members actual join wh_delta_members target on target.member_id = actual.id) <> 4
       or (select count(*) from public.sessions actual join wh_delta_sessions target on target.session_id = actual.id) <> 36 then
        raise exception 'West Houston final target-row set mismatch';
    end if;
    if exists (select 1 from wh_delta_members expected join public.members actual on actual.id = expected.member_id
        where actual.region_id <> '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid or actual.pax_name is distinct from expected.pax_name
           or actual.real_name is not null or actual.home_ao is distinct from expected.home_ao
           or actual.first_post_date <> expected.first_post_date::text or actual.status <> 'active') then
        raise exception 'West Houston final member content mismatch';
    end if;
    if exists (select 1 from wh_delta_expected_sessions expected join public.sessions actual on actual.id = expected.session_id
        cross join wh_delta_context context
        where actual.region_id <> '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid or actual.date <> expected.session_date::text
           or actual.ao_name is distinct from expected.ao_name or actual.ao_id is distinct from expected.ao_id
           or actual.site_id is distinct from expected.site_id or actual.q_id is distinct from expected.q_id
           or coalesce(actual.q_ids, '{}'::uuid[]) is distinct from expected.q_ids
           or coalesce(actual.attendee_ids, '[]'::jsonb) is distinct from expected.attendee_ids
           or coalesce(actual.fngs, '[]'::jsonb) is distinct from expected.fngs
           or actual.notes is distinct from expected.event_name
           or actual.created_at <> floor(extract(epoch from expected.session_date::timestamptz) * 1000)::bigint
           or actual.created_by_user_id is distinct from context.doge_profile_id or actual.start_time is not null
           or actual.attendance_review_status <> 'not_required') then
        raise exception 'West Houston final session content mismatch';
    end if;
    select count(*), coalesce(sum(jsonb_array_length(coalesce(attendee_ids, '[]'::jsonb))), 0),
           coalesce(sum(cardinality(coalesce(q_ids, '{}'::uuid[]))), 0),
           coalesce(sum(jsonb_array_length(coalesce(fngs, '[]'::jsonb))), 0)
    into actual_sessions, actual_attendance, actual_qs, actual_fngs
    from public.sessions where region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid;
    if actual_sessions <> 3778 or actual_attendance <> 43525
       or actual_qs <> 3671 or actual_fngs <> 497 then
        raise exception 'West Houston final totals mismatch: %/%/%/%', actual_sessions, actual_attendance, actual_qs, actual_fngs;
    end if;
    if exists (select 1 from wh_delta_preserved_members preserved
        left join public.members actual on actual.id = preserved.id
        where actual.id is null or to_jsonb(actual) is distinct from preserved.snapshot) then
        raise exception 'A pre-existing West Houston member was mutated or deleted';
    end if;
    if exists (select 1 from wh_delta_preserved_sessions preserved
        left join public.sessions actual on actual.id = preserved.id
        where actual.id is null or to_jsonb(actual) is distinct from preserved.snapshot) then
        raise exception 'A pre-existing West Houston session was mutated or deleted';
    end if;
    if exists (select 1 from wh_delta_members target
        left join public.region_participants participant
          on participant.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid and participant.member_id = target.member_id
        where participant.member_id is null or participant.status <> 'active'
           or not ('historic_import' = any(participant.sources))
           or not ('session_attendance' = any(participant.sources))) then
        raise exception 'West Houston delta participant synchronization mismatch';
    end if;
    if exists (select 1 from wh_delta_members target
        left join public.region_participants participant
          on participant.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid and participant.member_id = target.member_id
        left join lateral (select min(session.date::date) first_participated,
                                  max(session.date::date) last_participated
            from public.sessions session where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
              and coalesce(session.attendee_ids, '[]'::jsonb) ? target.member_id::text) attendance on true
        where participant.first_participated_on is distinct from attendance.first_participated
           or participant.last_participated_on is distinct from attendance.last_participated) then
        raise exception 'West Houston delta participant dates mismatch';
    end if;
    if exists (select 1 from wh_delta_members target
        left join public.member_stats stats on stats.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid and stats.member_id = target.member_id
        left join lateral (select count(*)::integer posts, min(session.date::date) first_post, max(session.date::date) last_post
            from public.sessions session where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
              and coalesce(session.attendee_ids, '[]'::jsonb) ? target.member_id::text) attendance on true
        left join lateral (select count(*)::integer qs, max(session.date::date) last_q
            from public.sessions session where session.region_id = '7298b632-4d9a-542f-b65d-d416e5c1e631'::uuid
              and target.member_id = any(coalesce(session.q_ids, '{}'::uuid[]))) q_history on true
        where stats.member_id is null or stats.total_posts <> attendance.posts or stats.total_qs <> q_history.qs
           or stats.last_post_date is distinct from attendance.last_post or stats.last_q_date is distinct from q_history.last_q
           or stats.first_post_date is distinct from (select member.first_post_date::date from public.members member where member.id = target.member_id)) then
        raise exception 'West Houston delta member statistics mismatch';
    end if;
end;
$wh_delta_postflight$;

commit;
